import sys


def _int_from_string(text: str, start: int, end: int) -> int:
    s = text[start:end]
    try:
        return int(s)
    except ValueError:
        try:
            sys.set_int_max_str_digits(0)
        except Exception:
            pass
        return int(s)


def parse_json(text: str) -> object:
    n = len(text)
    i = 0
    stack = []
    root = None
    done = False

    def skip_ws(pos: int) -> int:
        while pos < n:
            c = text[pos]
            if c == ' ' or c == '\t' or c == '\n' or c == '\r':
                pos += 1
            else:
                break
        return pos

    def read_hex4(pos: int) -> int:
        v = 0
        for k in range(pos, pos + 4):
            c = text[k]
            if '0' <= c <= '9':
                v = (v << 4) | (ord(c) - 48)
            elif 'A' <= c <= 'F':
                v = (v << 4) | (ord(c) - 55)
            elif 'a' <= c <= 'f':
                v = (v << 4) | (ord(c) - 87)
            else:
                raise ValueError
        return v

    def parse_string(pos: int) -> tuple[int, str]:
        if pos >= n or text[pos] != '"':
            raise ValueError
        pos += 1
        parts = []
        start = pos

        while pos < n:
            c = text[pos]

            if c == '"':
                parts.append(text[start:pos])
                return pos + 1, ''.join(parts)

            if c == '\\':
                parts.append(text[start:pos])
                pos += 1
                if pos >= n:
                    raise ValueError
                e = text[pos]
                pos += 1

                if e == '"':
                    parts.append('"')
                elif e == '\\':
                    parts.append('\\')
                elif e == '/':
                    parts.append('/')
                elif e == 'b':
                    parts.append('\b')
                elif e == 'f':
                    parts.append('\f')
                elif e == 'n':
                    parts.append('\n')
                elif e == 'r':
                    parts.append('\r')
                elif e == 't':
                    parts.append('\t')
                elif e == 'u':
                    if pos + 4 > n:
                        raise ValueError
                    cp = read_hex4(pos)
                    pos += 4

                    if 0xD800 <= cp <= 0xDBFF:
                        if pos + 6 > n or text[pos] != '\\' or text[pos + 1] != 'u':
                            raise ValueError
                        low = read_hex4(pos + 2)
                        pos += 6
                        if not (0xDC00 <= low <= 0xDFFF):
                            raise ValueError
                        parts.append(chr(0x10000 + ((cp - 0xD800) << 10) + (low - 0xDC00)))
                    elif 0xDC00 <= cp <= 0xDFFF:
                        raise ValueError
                    else:
                        parts.append(chr(cp))
                else:
                    raise ValueError

                start = pos
                continue

            if ord(c) < 32:
                raise ValueError
            pos += 1

        raise ValueError

    def parse_number(pos: int) -> tuple[int, object]:
        start = pos

        if text[pos] == '-':
            pos += 1
            if pos >= n:
                raise ValueError

        c = text[pos]
        if c == '0':
            pos += 1
            if pos < n and '0' <= text[pos] <= '9':
                raise ValueError
        elif '1' <= c <= '9':
            while pos < n and '0' <= text[pos] <= '9':
                pos += 1
        else:
            raise ValueError

        is_float = False

        if pos < n and text[pos] == '.':
            is_float = True
            pos += 1
            if pos >= n or not ('0' <= text[pos] <= '9'):
                raise ValueError
            while pos < n and '0' <= text[pos] <= '9':
                pos += 1

        if pos < n and (text[pos] == 'e' or text[pos] == 'E'):
            is_float = True
            pos += 1
            if pos < n and (text[pos] == '+' or text[pos] == '-'):
                pos += 1
            if pos >= n or not ('0' <= text[pos] <= '9'):
                raise ValueError
            while pos < n and '0' <= text[pos] <= '9':
                pos += 1

        if is_float:
            return pos, float(text[start:pos])
        return pos, _int_from_string(text, start, pos)

    def attach(value: object) -> None:
        nonlocal root, done

        if not stack:
            root = value
            done = True
            return

        frame = stack[-1]

        if frame[0] == 0:
            if frame[2] not in (0, 1):
                raise ValueError
            frame[1].append(value)
            frame[2] = 2
        else:
            if frame[2] != 2:
                raise ValueError
            frame[1][frame[3]] = value
            frame[2] = 3

    def parse_start_value(pos: int) -> int:
        if pos >= n:
            raise ValueError
        c = text[pos]

        if c == '{':
            stack.append([1, {}, 0, None])
            return pos + 1

        if c == '[':
            stack.append([0, [], 0, None])
            return pos + 1

        if c == '"':
            pos, value = parse_string(pos)
            attach(value)
            return pos

        if c == 't':
            if pos + 4 > n or text[pos:pos + 4] != 'true':
                raise ValueError
            attach(True)
            return pos + 4

        if c == 'f':
            if pos + 5 > n or text[pos:pos + 5] != 'false':
                raise ValueError
            attach(False)
            return pos + 5

        if c == 'n':
            if pos + 4 > n or text[pos:pos + 4] != 'null':
                raise ValueError
            attach(None)
            return pos + 4

        if c == '-' or '0' <= c <= '9':
            pos, value = parse_number(pos)
            attach(value)
            return pos

        raise ValueError

    while not done:
        if not stack:
            i = skip_ws(i)
            if i >= n:
                raise ValueError
            i = parse_start_value(i)
            continue

        frame = stack[-1]
        i = skip_ws(i)
        if i >= n:
            raise ValueError
        c = text[i]

        if frame[0] == 0:
            state = frame[2]

            if state == 0:
                if c == ']':
                    i += 1
                    container = frame[1]
                    stack.pop()
                    attach(container)
                elif c == ',':
                    raise ValueError
                else:
                    i = parse_start_value(i)

            elif state == 1:
                if c == ']' or c == ',':
                    raise ValueError
                else:
                    i = parse_start_value(i)

            else:
                if c == ']':
                    i += 1
                    container = frame[1]
                    stack.pop()
                    attach(container)
                elif c == ',':
                    i += 1
                    frame[2] = 1
                else:
                    raise ValueError

        else:
            state = frame[2]

            if state == 0:
                if c == '}':
                    i += 1
                    container = frame[1]
                    stack.pop()
                    attach(container)
                elif c == ',':
                    raise ValueError
                elif c == '"':
                    i, key = parse_string(i)
                    if key in frame[1]:
                        raise ValueError
                    i = skip_ws(i)
                    if i >= n or text[i] != ':':
                        raise ValueError
                    i += 1
                    frame[3] = key
                    frame[2] = 2
                else:
                    raise ValueError

            elif state == 1:
                if c == '}' or c == ',' or c != '"':
                    raise ValueError
                i, key = parse_string(i)
                if key in frame[1]:
                    raise ValueError
                i = skip_ws(i)
                if i >= n or text[i] != ':':
                    raise ValueError
                i += 1
                frame[3] = key
                frame[2] = 2

            elif state == 2:
                i = parse_start_value(i)

            else:
                if c == '}':
                    i += 1
                    container = frame[1]
                    stack.pop()
                    attach(container)
                elif c == ',':
                    i += 1
                    frame[2] = 1
                else:
                    raise ValueError

    i = skip_ws(i)
    if i != n:
        raise ValueError

    return root
